async function carePage(){main.innerHTML='<section class="loading-card"><span class="spinner"></span><p>載入住宿中貓咪…</p></section>';try{const stays=state.cloud?await state.repo.activeStays():demoStays(),cats=flattenStayCats(stays);main.innerHTML=`<div class="page-head"><div><p>每隻貓獨立紀錄；未知不等於正常</p><h2>每日照護</h2></div><button class="btn secondary" id="backMore">返回</button></div>${!state.cloud?'<div class="dev-banner">合成資料唯讀預覽</div>':''}${cats.length?`<section class="card"><div class="form-grid two"><div class="field"><label>住宿中貓咪</label><select id="careCat">${cats.map(c=>`<option value="${c.reservationCatId}">${esc(c.catName)}｜${esc(c.roomName)}</option>`).join('')}</select></div><div class="field"><label>照護日期</label><input id="careDate" type="date" value="${taipeiDate()}"></div></div><div id="careSnapshot" class="notice"></div><div class="actions">${[['meal','＋ 餐點'],['water','＋ 飲水'],['urination','＋ 排尿'],['defecation','＋ 排便'],['activity','＋ 活動']].map(([type,label])=>`<button class="btn secondary" data-care-add="${type}" ${!state.cloud?'disabled':''}>${label}</button>`).join('')}</div></section><section id="careRecords" style="margin-top:14px"></section>`:'<div class="empty-state"><h3>目前沒有住宿中的貓咪</h3><p>完成預約的入住流程後，才會建立照護日期。</p></div>'}`;document.querySelector('#backMore').onclick=()=>route('more');if(!cats.length)return;const catSelect=document.querySelector('#careCat'),dateInput=document.querySelector('#careDate'),records=document.querySelector('#careRecords');const refresh=async()=>{const ctx=cats.find(c=>c.reservationCatId===catSelect.value);document.querySelector('#careSnapshot').innerHTML=`<strong>${esc(ctx.catName)}｜住宿照護快照</strong><br>${esc(ctx.snapshot.special_care||'沒有已確認的特殊照護文字；請勿推定為一般照護。')}`;records.innerHTML='<section class="loading-card"><span class="spinner"></span></section>';const day=state.cloud?await state.repo.careDay(ctx.reservationCatId,dateInput.value):demoCareDay(dateInput.value);records.innerHTML=careDayMarkup(day,dateInput.value)};catSelect.onchange=refresh;dateInput.onchange=refresh;document.querySelectorAll('[data-care-add]').forEach(button=>button.onclick=()=>{const ctx=cats.find(c=>c.reservationCatId===catSelect.value);careRecordDialog(button.dataset.careAdd,ctx,dateInput.value,refresh)});await refresh()}catch(error){renderFatal(error)}}
function demoCareDay(date){return{id:'demo-day',day_number:1,care_date:date,meal_records:[{id:'m1',label:'早餐',status:'finished',actual_feeding_at:new Date().toISOString(),offered_quantity:35,consumed_quantity:35,unit:'g',notes:'食慾正常（合成資料）'}],water_records:[],urination_records:[{id:'u1',observed_at:new Date().toISOString(),observation_state:'normal',clump_count:2}],defecation_records:[],activity_records:[]}}
function careDayMarkup(day,date){if(!day)return`<div class="empty-state"><h3>${esc(date)} 尚無紀錄</h3><p>尚未觀察或尚未填寫，不會顯示為正常。</p></div>`;const groups=[['餐點',day.meal_records,r=>`${r.label}｜${r.status}｜${r.actual_feeding_at?formatTaipei(r.actual_feeding_at):'尚未餵食'}`],['飲水',day.water_records,r=>`${r.observation}｜${formatTaipei(r.observed_at)}`],['排尿',day.urination_records,r=>`${r.observation_state}｜尿塊 ${r.clump_count??'未記錄'}｜${formatTaipei(r.observed_at)}`],['排便',day.defecation_records,r=>`${r.observation_state}｜${r.consistency||'形態未記錄'}｜${formatTaipei(r.observed_at)}`],['活動與其他',day.activity_records,r=>`${r.activity||'活動未記錄'}｜${r.mood||'情緒未記錄'}｜${formatTaipei(r.observed_at)}`]];return`<div class="page-head"><div><p>Day ${day.day_number}</p><h2>${esc(day.care_date)}</h2></div></div><div class="grid rooms">${groups.map(([title,rows,format])=>`<section class="card"><h3>${title}</h3><div class="list">${rows?.length?rows.map(r=>`<div class="list-item"><div>${esc(format(r))}<p>${esc(r.notes||'')}</p></div></div>`).join(''):'<p class="muted">尚無紀錄</p>'}</div></section>`).join('')}</div>`}
const triState=(name,label)=>`<div class="field"><label>${label}</label><select name="${name}"><option value="">未觀察／未知</option><option value="true">是</option><option value="false">否</option></select></div>`;
function careRecordFields(type){const observed=`<div class="field"><label>觀察時間 *</label><input name="observedAt" type="datetime-local" required value="${taipeiDateTimeInput()}"></div>`;if(type==='meal')return`<div class="form-grid two"><div class="field"><label>餐次 *</label><input name="label" required maxlength="50" placeholder="早餐、午餐、晚餐或加餐"></div><div class="field"><label>狀態 *</label><select name="status" required><option value="pending">待處理</option><option value="offered">已提供</option><option value="finished">吃完</option><option value="small_remaining">剩少量</option><option value="half_eaten">吃一半</option><option value="small_eaten">吃少量</option><option value="not_eaten">未進食</option><option value="observing">待觀察</option><option value="not_applicable">不適用</option></select></div><div class="field"><label>實際餵食時間</label><input name="actualAt" type="datetime-local" value="${taipeiDateTimeInput()}"></div><div class="field"><label>單位</label><input name="unit" maxlength="20" placeholder="g、罐、包"></div><div class="field"><label>計畫量</label><input name="plannedQuantity" type="number" min="0" step="0.001"></div><div class="field"><label>實際提供量</label><input name="offeredQuantity" type="number" min="0" step="0.001"></div><div class="field"><label>剩餘食物</label><input name="remainingQuantity" type="number" min="0" step="0.001"></div><div class="field"><label>已吃量（確定時才填）</label><input name="consumedQuantity" type="number" min="0" step="0.001"></div></div><div class="field"><label>不適用原因</label><input name="notApplicableReason" maxlength="500"></div>`;if(type==='water')return`${observed}<div class="form-grid two"><div class="field"><label>觀察 *</label><select name="observation"><option value="not_observed">未觀察</option><option value="normal">正常</option><option value="less">比平常少</option><option value="more">比平常多</option><option value="unknown">不確定</option></select></div><div class="field"><label>可量測飲水量</label><input name="amount" type="number" min="0" step="0.001"></div><div class="field"><label>單位</label><input name="unit" value="ml" maxlength="20"></div>${triState('replaced','已更換飲水')}</div>`;if(type==='urination')return`${observed}<div class="field"><label>觀察狀態 *</label><select name="state"><option value="not_yet_observed">尚未觀察</option><option value="none_observed">未發現排尿</option><option value="normal">一般觀察</option><option value="abnormal">異常觀察</option></select></div><div class="form-grid two"><div class="field"><label>尿塊數</label><input name="clumpCount" type="number" min="0" step="1"></div><div class="field"><label>尿塊大小</label><input name="clumpSize" maxlength="100"></div><div class="field"><label>顏色</label><input name="color" maxlength="100"></div>${triState('suspectedBlood','疑似血尿')}${triState('repeatedVisits','反覆進出貓砂盆')}${triState('unusualBehavior','異常行為')}</div><div class="notice danger">疑似無法排尿時，請立即聯絡主管與獸醫。</div>`;if(type==='defecation')return`${observed}<div class="field"><label>觀察狀態 *</label><select name="state"><option value="not_yet_observed">尚未觀察</option><option value="none_observed">未發現排便</option><option value="normal">一般觀察</option><option value="abnormal">異常觀察</option></select></div><div class="form-grid two"><div class="field"><label>數量</label><input name="quantity" maxlength="100"></div><div class="field"><label>形態</label><select name="consistency"><option value="">未知／未記錄</option><option value="formed">成形</option><option value="hard">偏硬</option><option value="soft">軟便</option><option value="diarrhea">腹瀉</option><option value="unknown">無法判斷</option></select></div>${triState('unusualColor','異常顏色')}${triState('suspectedBlood','疑似血便')}</div>`;return`${observed}<div class="form-grid two"><div class="field"><label>活動</label><input name="activity" maxlength="200"></div><div class="field"><label>情緒</label><input name="mood" maxlength="200"></div><div class="field"><label>互動</label><input name="socialInteraction" maxlength="200"></div>${triState('hidingBehavior','躲藏')}${triState('vomiting','嘔吐')}${triState('scratching','抓癢')}${triState('visibleInjury','可見受傷')}${triState('cleaningCompleted','清潔完成')}</div>`}
function careRecordDialog(type,ctx,date,refresh){const names={meal:'餐點',water:'飲水',urination:'排尿',defecation:'排便',activity:'活動與其他'},dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><div class="drawer-head"><div><p class="eyebrow">${esc(ctx.catName)}｜${esc(date)}</p><h2>新增${names[type]}紀錄</h2></div><button class="icon-btn" aria-label="關閉">✕</button></div><form>${careRecordFields(type)}<div class="field"><label>備註</label><textarea name="notes" maxlength="2000"></textarea></div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">儲存紀錄</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form'),tri=value=>value===''?null:value==='true';form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;setSync('儲存中','saving');try{const careDayId=await state.repo.ensureCareDay(ctx.reservationCatId,date);let payload={careDayId,notes:data.notes?.trim()||null};if(type==='meal')payload={...payload,label:data.label,status:data.status,actualAt:data.actualAt?taipeiInputToIso(data.actualAt):null,plannedQuantity:data.plannedQuantity||null,offeredQuantity:data.offeredQuantity||null,remainingQuantity:data.remainingQuantity||null,consumedQuantity:data.consumedQuantity||null,unit:data.unit?.trim()||null,notApplicableReason:data.notApplicableReason?.trim()||null};else if(type==='water')payload={...payload,observedAt:taipeiInputToIso(data.observedAt),observation:data.observation,amount:data.amount||null,unit:data.unit?.trim()||null,replaced:tri(data.replaced)};else if(type==='urination')payload={...payload,observedAt:taipeiInputToIso(data.observedAt),state:data.state,clumpCount:data.clumpCount||null,clumpSize:data.clumpSize?.trim()||null,color:data.color?.trim()||null,suspectedBlood:tri(data.suspectedBlood),repeatedVisits:tri(data.repeatedVisits),unusualBehavior:tri(data.unusualBehavior)};else if(type==='defecation')payload={...payload,observedAt:taipeiInputToIso(data.observedAt),state:data.state,quantity:data.quantity?.trim()||null,consistency:data.consistency||null,unusualColor:tri(data.unusualColor),suspectedBlood:tri(data.suspectedBlood)};else payload={...payload,observedAt:taipeiInputToIso(data.observedAt),activity:data.activity?.trim()||null,mood:data.mood?.trim()||null,socialInteraction:data.socialInteraction?.trim()||null,hidingBehavior:tri(data.hidingBehavior),vomiting:tri(data.vomiting),scratching:tri(data.scratching),visibleInjury:tri(data.visibleInjury),cleaningCompleted:tri(data.cleaningCompleted)};await state.repo.createCareRecord(type,payload);setSync('已儲存');dialog.close();await refresh()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false;setSync('儲存失敗','error')}};closeDialogHandlers(dialog);dialog.showModal()}
async function itemsPage(){main.innerHTML='<section class="loading-card"><span class="spinner"></span><p>載入入住物品…</p></section>';try{const stays=state.cloud?await state.repo.activeStays():demoStays(),categories=state.cloud?await state.repo.itemCategories():ITEM_CATEGORIES.map((name,i)=>({id:`demo-category-${i}`,name}));main.innerHTML=`<div class="page-head"><div><p>物品綁定本次住宿，不修改永久貓咪資料</p><h2>入住物品</h2></div><button class="btn secondary" id="backMore">返回</button></div>${!state.cloud?'<div class="dev-banner">合成資料唯讀預覽</div>':''}${stays.length?`<section class="card"><div class="field"><label>住宿</label><select id="itemStay">${stays.map(s=>`<option value="${s.id}">${esc(s.reservation_number)}｜${esc(s.reservation_cats.map(rc=>rc.cats?.name).join('、'))}</option>`).join('')}</select></div><button class="btn" id="addItem" ${!state.cloud?'disabled':''}>＋ 登記物品</button></section><section id="itemList" class="grid rooms" style="margin-top:14px"></section>`:'<div class="empty-state"><p>目前沒有住宿中的預約。</p></div>'}`;document.querySelector('#backMore').onclick=()=>route('more');if(!stays.length)return;const select=document.querySelector('#itemStay'),list=document.querySelector('#itemList');const refresh=async()=>{list.innerHTML='<section class="loading-card"><span class="spinner"></span></section>';const items=state.cloud?await state.repo.stayItems(select.value):[{id:'demo-item',name:'乾飼料',received_quantity:1200,remaining_quantity:880,unit:'g',storage_location:'A 櫃 2 層',usage_instructions:'早餐 35g',return_required:true,stay_item_categories:{name:'乾飼料'},reservation_cats:{cats:{name:'木木'}}}];list.innerHTML=itemCards(items)};select.onchange=refresh;if(state.cloud)document.querySelector('#addItem').onclick=()=>itemDialog(stays.find(s=>s.id===select.value),categories,refresh);await refresh()}catch(error){renderFatal(error)}}
function itemCards(items){if(!items.length)return'<div class="empty-state"><p>尚未登記本次住宿物品。</p></div>';return items.map(i=>`<article class="card"><div class="page-head"><div><p>${esc(i.stay_item_categories?.name||'未分類')}</p><h3>${esc(i.name)}</h3></div><span class="badge">${i.reservation_cats?.cats?.name?esc(i.reservation_cats.cats.name):'共用'}</span></div><p><strong>剩餘：</strong>${i.remaining_quantity??'未知'} ${esc(i.unit||'')}</p><p><strong>位置：</strong>${esc(i.storage_location||'未記錄')}</p><p class="muted">${esc(i.usage_instructions||i.special_instructions||'沒有使用說明')}</p>${i.return_required?'<span class="badge danger">退房需歸還／核對</span>':'<span class="badge">不需歸還</span>'}</article>`).join('')}
function itemDialog(stay,categories,refresh){const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><div class="drawer-head"><h2>登記入住物品</h2><button class="icon-btn" aria-label="關閉">✕</button></div><form><div class="field"><label>使用對象 *</label><select name="target" required><option value="shared">多貓共用物品</option>${stay.reservation_cats.map(rc=>`<option value="${rc.id}">${esc(rc.cats?.name)}</option>`).join('')}</select></div><div class="form-grid two"><div class="field"><label>分類 *</label><select name="categoryId" required>${categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>名稱 *</label><input name="name" required maxlength="200"></div><div class="field"><label>收到數量</label><input name="quantity" type="number" min="0" step="0.001" placeholder="未知可留白"></div><div class="field"><label>單位</label><input name="unit" maxlength="30" placeholder="個、包、g、ml"></div></div><div class="field"><label>存放位置</label><input name="storageLocation" maxlength="200"></div><div class="field"><label>使用說明</label><textarea name="usageInstructions" maxlength="2000"></textarea></div><div class="field"><label>特殊指示</label><textarea name="specialInstructions" maxlength="2000"></textarea></div><label class="list-item"><span>退房時需歸還或核對</span><input style="width:auto" type="checkbox" name="returnRequired" checked></label><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">儲存物品</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;setSync('儲存中','saving');try{await state.repo.createStayItem({reservationId:stay.id,reservationCatId:d.target==='shared'?null:d.target,shared:d.target==='shared',categoryId:d.categoryId,name:d.name,quantity:d.quantity||null,unit:d.unit,storageLocation:d.storageLocation,usageInstructions:d.usageInstructions,specialInstructions:d.specialInstructions,returnRequired:form.elements.returnRequired.checked});setSync('已儲存');dialog.close();await refresh()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false;setSync('儲存失敗','error')}};closeDialogHandlers(dialog);dialog.showModal()}
const EVENT_CATEGORIES=[['appetite','食慾'],['water','飲水'],['urination','排尿'],['defecation','排便'],['vomiting','嘔吐'],['low_activity','活動力低落'],['injury','受傷'],['behavior','行為'],['medication','用藥'],['other','其他']];
const SEVERITIES=[['observation','觀察'],['follow_up','需追蹤'],['high','高優先'],['emergency','緊急']];
async function eventsPage(){main.innerHTML='<section class="loading-card"><span class="spinner"></span><p>載入異常事件…</p></section>';try{const stays=state.cloud?await state.repo.activeStays():demoStays(),cats=flattenStayCats(stays),events=state.cloud?await state.repo.abnormalEvents():[{id:'demo-event',category:'appetite',severity:'follow_up',event_at:new Date().toISOString(),description:'早餐食量比平常少，持續觀察中（合成資料）',follow_up_required:true,status:'monitoring',reservation_cats:{cats:{name:'木木'},reservations:{reservation_number:'DEMO-STAY'}}}];main.innerHTML=`<div class="page-head"><div><p>未結案事件跨日期與班別持續顯示</p><h2>異常紀錄</h2></div><div class="actions"><button class="btn secondary" id="backMore">返回</button><button class="btn" id="addEvent" ${!state.cloud||!cats.length?'disabled':''}>＋ 回報</button></div></div>${!state.cloud?'<div class="dev-banner">合成資料唯讀預覽</div>':''}<div class="notice danger"><strong>這是紀錄與通知系統，不是獸醫診斷系統。</strong><br>疑似無法排尿或呼吸困難，請立即聯絡主管與獸醫。</div><section class="list">${eventCards(events)}</section>`;document.querySelector('#backMore').onclick=()=>route('more');if(state.cloud&&cats.length)document.querySelector('#addEvent').onclick=()=>abnormalEventDialog(cats,eventsPage)}catch(error){renderFatal(error)}}
function eventCards(events){if(!events.length)return'<div class="empty-state"><p>沒有異常事件。</p></div>';return events.map(event=>{const category=EVENT_CATEGORIES.find(([key])=>key===event.category)?.[1]||event.category,severity=SEVERITIES.find(([key])=>key===event.severity)?.[1]||event.severity;return`<article class="card ${event.severity==='emergency'||event.severity==='high'?'urgent':''}"><div class="page-head"><div><p>${esc(event.reservation_cats?.cats?.name||'未連結貓咪')}｜${esc(formatTaipei(event.event_at))}</p><h3>${esc(category)}</h3></div><span class="badge ${event.severity==='emergency'||event.severity==='high'?'danger':''}">${esc(severity)}</span></div><p>${esc(event.description)}</p><div class="actions"><span class="badge">${esc(event.status)}</span>${event.follow_up_required?'<span class="badge danger">需要追蹤</span>':''}</div></article>`}).join('')}
function abnormalEventDialog(cats,refresh){const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><div class="drawer-head"><h2>回報異常事件</h2><button class="icon-btn" aria-label="關閉">✕</button></div><form><div class="field"><label>貓咪 *</label><select name="reservationCatId" required>${cats.map(c=>`<option value="${c.reservationCatId}">${esc(c.catName)}｜${esc(c.roomName)}</option>`).join('')}</select></div><div class="form-grid two"><div class="field"><label>類別 *</label><select name="category">${EVENT_CATEGORIES.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div><div class="field"><label>嚴重度 *</label><select name="severity">${SEVERITIES.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div><div class="field"><label>事件時間 *</label><input name="eventAt" type="datetime-local" required value="${taipeiDateTimeInput()}"></div><div class="field"><label>下次追蹤時間</label><input name="nextFollowUp" type="datetime-local"></div></div><div class="field"><label>實際觀察說明 *</label><textarea name="description" required maxlength="4000" placeholder="只記錄觀察到的事實，不做診斷"></textarea></div><label class="list-item"><span>需要後續追蹤</span><input style="width:auto" type="checkbox" name="followUp"></label><div class="notice danger" id="urgentNotice" hidden>緊急事件請先聯絡主管與獸醫，再完成紀錄。</div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">儲存事件</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form'),urgent=dialog.querySelector('#urgentNotice');form.elements.severity.onchange=()=>urgent.hidden=form.elements.severity.value!=='emergency';form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;setSync('儲存中','saving');try{await state.repo.createAbnormalEvent({reservationCatId:d.reservationCatId,category:d.category,severity:d.severity,eventAt:taipeiInputToIso(d.eventAt),description:d.description,followUp:form.elements.followUp.checked||['follow_up','high','emergency'].includes(d.severity),nextFollowUp:d.nextFollowUp?taipeiInputToIso(d.nextFollowUp):null});setSync('已儲存');dialog.close();await refresh()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false;setSync('儲存失敗','error')}};closeDialogHandlers(dialog);dialog.showModal()}
function demoStaffOps(){const now=new Date(),end=new Date(now.getTime()+8*3600000);return{staff:[{user_id:'demo-user',display_name:'示範保母',role:'staff',status:'active'},{user_id:'demo-manager',display_name:'示範主管',role:'manager',status:'active'}],shifts:[{id:'demo-shift',staff_user_id:'demo-user',starts_at:now.toISOString(),ends_at:end.toISOString(),actual_start_at:now.toISOString(),status:'active',version:1}],handovers:[{id:'demo-handover',from_shift_id:'demo-shift',to_user_id:'demo-manager',important:true,notes:'奶茶晚間用藥後需持續觀察食慾（合成資料）',acknowledged_at:null,created_at:now.toISOString(),version:1,reservations:{reservation_number:'DEMO-STAY'}}]}}
async function handoverPage(){main.innerHTML='<section class="loading-card"><span class="spinner"></span><p>載入班表與交接…</p></section>';try{const data=state.cloud?{staff:await state.repo.staff(),shifts:await state.repo.shifts(),handovers:await state.repo.handovers()}:demoStaffOps(),canSchedule=['owner','manager'].includes(state.membership?.role),currentUser=state.session?.user?.id||'demo-user',staffName=id=>data.staff.find(s=>s.user_id===id)?.display_name||'未指定';main.innerHTML=`<div class="page-head"><div><p>未完成工作不會自動結案</p><h2>班表與保母交接</h2></div><div class="actions"><button class="btn secondary" id="backMore">返回</button>${canSchedule?'<button class="btn" id="scheduleShift">＋ 排班</button>':''}</div></div>${!state.cloud?'<div class="dev-banner">合成資料唯讀預覽</div>':''}<section class="card"><div class="page-head"><h3>近期班別</h3><button class="btn secondary" id="viewNotifications">明日通知</button></div><div class="list">${data.shifts.length?data.shifts.map(shift=>`<article class="list-item"><div><strong>${esc(staffName(shift.staff_user_id))}</strong><p>${esc(formatTaipei(shift.starts_at))} → ${esc(formatTaipei(shift.ends_at))}</p><span class="badge">${esc(shift.status)}</span></div><div class="actions">${shift.status==='scheduled'?`<button class="btn secondary" data-start-shift="${shift.id}" ${!state.cloud||(!canSchedule&&shift.staff_user_id!==currentUser)?'disabled':''}>上班</button>`:''}${['active','handover_required'].includes(shift.status)?`<button class="btn secondary" data-new-handover="${shift.id}" ${!state.cloud?'disabled':''}>新增交接</button><button class="btn" data-complete-shift="${shift.id}" ${!state.cloud||(!canSchedule&&shift.staff_user_id!==currentUser)?'disabled':''}>交班下班</button>`:''}</div></article>`).join(''):'<p class="muted">沒有近期班別</p>'}</div></section><section class="card" style="margin-top:14px"><h3>交接紀錄</h3><div class="list">${data.handovers.length?data.handovers.map(h=>`<article class="list-item"><div><strong>${h.important?'重要交接':'一般交接'}｜${esc(staffName(h.to_user_id))}</strong><p>${esc(h.notes)}</p><span class="muted">${esc(h.reservations?.reservation_number||'全館')}｜${esc(formatTaipei(h.created_at))}</span></div>${h.acknowledged_at?'<span class="badge ok">已確認</span>':`<button class="btn secondary" data-ack-handover="${h.id}" ${!state.cloud||(!canSchedule&&h.to_user_id&&h.to_user_id!==currentUser)?'disabled':''}>確認收到</button>`}</article>`).join(''):'<p class="muted">尚無交接紀錄</p>'}</div></section>`;document.querySelector('#backMore').onclick=()=>navigate('more');document.querySelector('#viewNotifications').onclick=()=>navigate('notifications');if(canSchedule)document.querySelector('#scheduleShift').onclick=()=>scheduleShiftDialog(data.staff,handoverPage);main.onclick=async e=>{const start=e.target.closest('[data-start-shift]'),complete=e.target.closest('[data-complete-shift]'),create=e.target.closest('[data-new-handover]'),ack=e.target.closest('[data-ack-handover]');try{if(start){const shift=data.shifts.find(s=>s.id===start.dataset.startShift);await state.repo.startShift(shift.id,shift.version);return handoverPage()}if(complete){const shift=data.shifts.find(s=>s.id===complete.dataset.completeShift);return completeShiftDialog(shift,handoverPage)}if(create){const shift=data.shifts.find(s=>s.id===create.dataset.newHandover);return handoverDialog(shift,data.staff,handoverPage)}if(ack){const h=data.handovers.find(x=>x.id===ack.dataset.ackHandover);await state.repo.acknowledgeHandover(h.id,h.version);return handoverPage()}}catch(error){alert(error.message)}}}catch(error){renderFatal(error)}}
function scheduleShiftDialog(staff,refresh){const dialog=document.createElement('dialog'),start=new Date(),end=new Date(start.getTime()+8*3600000);dialog.innerHTML=`<div class="dialog-body"><h2>新增班別</h2><form><div class="field"><label>人員</label><select name="staffUserId">${staff.filter(s=>s.status==='active').map(s=>`<option value="${s.user_id}">${esc(s.display_name)}｜${esc(s.role)}</option>`).join('')}</select></div><div class="form-grid two"><div class="field"><label>開始</label><input name="startsAt" type="datetime-local" required value="${taipeiDateTimeInput(start)}"></div><div class="field"><label>結束</label><input name="endsAt" type="datetime-local" required value="${taipeiDateTimeInput(end)}"></div></div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">建立班別</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;try{await state.repo.scheduleShift({staffUserId:d.staffUserId,startsAt:taipeiInputToIso(d.startsAt),endsAt:taipeiInputToIso(d.endsAt)});dialog.close();await refresh()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false}};closeDialogHandlers(dialog);dialog.showModal()}
async function handoverDialog(shift,staff,refresh){const reservations=await state.repo.reservations(),dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><h2>新增交接</h2><form><div class="field"><label>接班人</label><select name="toUserId"><option value="">全班共用</option>${staff.filter(s=>s.status==='active'&&s.user_id!==shift.staff_user_id).map(s=>`<option value="${s.user_id}">${esc(s.display_name)}</option>`).join('')}</select></div><div class="field"><label>相關預約</label><select name="reservationId"><option value="">全館事項</option>${reservations.filter(r=>!['checked_out','cancelled'].includes(r.status)).map(r=>`<option value="${r.id}">${esc(r.reservation_number)}｜${esc(r.reservation_cats.map(c=>c.cats?.name).join('、'))}</option>`).join('')}</select></div><label class="list-item"><span>重要交接（需要確認）</span><input style="width:auto" name="important" type="checkbox"></label><div class="field"><label>交接內容 *</label><textarea name="notes" required maxlength="3000"></textarea></div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">建立交接</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;try{await state.repo.createHandover({fromShiftId:shift.id,toUserId:d.toUserId,reservationId:d.reservationId,important:form.elements.important.checked,notes:d.notes});dialog.close();await refresh()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false}};closeDialogHandlers(dialog);dialog.showModal()}
async function completeShiftDialog(shift,refresh){let summary;try{summary=await state.repo.shiftSummary(shift.id)}catch(error){return alert(error.message)}const dialog=document.createElement('dialog'),labels={pending_tasks:'待處理工作',pending_medications:'待處理用藥',unresolved_events:'未結案異常',pending_notifications:'待通知飼主',pending_cleaning:'待清潔房間',unacknowledged_handovers:'未確認重要交接'};dialog.innerHTML=`<div class="dialog-body"><h2>交班前檢查</h2><div class="grid stats">${Object.entries(labels).map(([key,label])=>`<div class="card stat ${summary[key]?'urgent':''}"><small>${label}</small><strong>${Number(summary[key]||0)}</strong></div>`).join('')}</div><form><div class="field" style="margin-top:14px"><label>仍有未完成事項時，請記錄轉交或例外原因</label><textarea name="exception" maxlength="2000"></textarea></div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">確認交班並下班</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await state.repo.completeShift(shift.id,shift.version,form.elements.exception.value.trim());dialog.close();await refresh()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false}};closeDialogHandlers(dialog);dialog.showModal()}
function demoNotifications(){return[{id:'demo-notification',notification_type:'next_day_checkin',target_date:addLocalDays(taipeiDate(),1),status:'pending',message:'示範飼主您好，提醒您明日 15:00 帶木木入住暮貓旅宿。請記得攜帶已確認的食物、藥品與用品，謝謝。',version:1,reservations:{reservation_number:'DEMO-STAY',owners:{name:'示範飼主'},reservation_cats:[{cats:{name:'木木'}}]}}]}
async function notificationsPage(){main.innerHTML='<section class="loading-card"><span class="spinner"></span><p>載入通知任務…</p></section>';try{const notifications=state.cloud?await state.repo.notifications():demoNotifications();main.innerHTML=`<div class="page-head"><div><p>複製訊息不等於已送出</p><h2>明日入住／退房通知</h2></div><button class="btn secondary" id="backTasks">返回待辦</button></div>${!state.cloud?'<div class="dev-banner">合成資料唯讀預覽</div>':''}<section class="list">${notifications.length?notifications.map(n=>`<article class="card"><div class="page-head"><div><p>${esc(n.reservations?.reservation_number||'')}</p><h3>${n.notification_type==='next_day_checkin'?'明日入住':'明日退房'}｜${esc(n.reservations?.owners?.name||'')}</h3></div><span class="badge">${esc(n.status)}</span></div><div class="field"><label>LINE-ready 訊息</label><textarea readonly rows="6" data-message>${esc(n.message)}</textarea></div><div class="actions"><button class="btn secondary" data-copy-notification="${n.id}" ${!state.cloud?'disabled':''}>複製訊息</button><button class="btn" data-sent-notification="${n.id}" ${!state.cloud?'disabled':''}>標記已送出</button>${n.status==='sent'?`<button class="btn secondary" data-wait-notification="${n.id}">等待回覆</button><button class="btn secondary" data-confirm-notification="${n.id}">已確認</button>`:''}</div><p class="muted">目標日期 ${esc(n.target_date)}${n.actual_notified_at?`｜實際通知 ${esc(formatTaipei(n.actual_notified_at))}`:''}</p></article>`).join(''):'<div class="empty-state"><p>目前沒有待處理通知。</p></div>'}</section>`;document.querySelector('#backTasks').onclick=()=>navigate('tasks');main.onclick=async e=>{const copy=e.target.closest('[data-copy-notification]'),sent=e.target.closest('[data-sent-notification]'),wait=e.target.closest('[data-wait-notification]'),confirm=e.target.closest('[data-confirm-notification]'),button=copy||sent||wait||confirm;if(!button)return;const id=button.dataset.copyNotification||button.dataset.sentNotification||button.dataset.waitNotification||button.dataset.confirmNotification,item=notifications.find(n=>n.id===id);try{if(copy){const message=copy.closest('.card').querySelector('[data-message]').value;await navigator.clipboard.writeText(message);await state.repo.transitionNotification(id,'message_copied',item.version);setSync('訊息已複製；尚未標記送出')}else if(sent)return notificationSentDialog(item,notificationsPage);else if(wait)await state.repo.transitionNotification(id,'waiting_response',item.version);else if(confirm)await state.repo.transitionNotification(id,'confirmed',item.version);await notificationsPage()}catch(error){alert(`通知狀態未更新：${error.message}`)}}}catch(error){renderFatal(error)}}
function notificationSentDialog(item,refresh){const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><h2>確認實際送出</h2><p>只有已透過 LINE 或其他管道實際傳送後才能確認。</p><form><div class="field"><label>通知管道 *</label><select name="channel"><option value="LINE">LINE</option><option value="phone">電話</option><option value="email">Email</option><option value="other">其他</option></select></div><div class="field"><label>備註</label><textarea name="notes" maxlength="1000"></textarea></div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">確認已送出</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await state.repo.transitionNotification(item.id,'sent',item.version,{channel:form.elements.channel.value,notes:form.elements.notes.value.trim()});dialog.close();await refresh()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false}};closeDialogHandlers(dialog);dialog.showModal()}
async function profilesPage(){if(!state.cloud)return sectionInfoFallback('飼主與貓咪資料','連接 Supabase 後可建立永久檔案，住宿時會另外建立照護快照。');main.innerHTML='<section class="loading-card"><span class="spinner"></span><p>載入飼主資料…</p></section>';try{const owners=await state.repo.ownersAndCats();main.innerHTML=`<div class="page-head"><div><p>永久資料與住宿快照分離</p><h2>飼主與貓咪資料</h2></div><div class="actions"><button class="btn secondary" id="backMore">返回</button><button class="btn" id="addOwner">＋ 飼主</button></div></div><div class="toolbar"><input id="profileSearch" type="search" placeholder="搜尋飼主、電話或貓咪"></div><section id="ownerList" class="grid rooms">${ownerCards(owners)}</section>`;document.querySelector('#backMore').onclick=()=>route('more');document.querySelector('#addOwner').onclick=ownerDialog;document.querySelector('#profileSearch').oninput=e=>{const q=e.target.value.trim().toLowerCase();document.querySelector('#ownerList').innerHTML=ownerCards(owners.filter(o=>JSON.stringify(o).toLowerCase().includes(q)))};document.querySelector('#ownerList').onclick=e=>{const button=e.target.closest('[data-add-cat]');if(button)catDialog(button.dataset.addCat,owners.find(o=>o.id===button.dataset.addCat)?.name)}}catch(error){renderFatal(error)}}
function ownerCards(owners){if(!owners.length)return'<div class="empty-state"><p>尚無飼主資料，先建立第一位飼主。</p></div>';return owners.map(o=>`<article class="card"><h3>${esc(o.name)}</h3><p class="muted">${esc(o.phone)}</p><div class="list">${o.cats?.length?o.cats.map(c=>`<div class="list-item"><span>🐈 ${esc(c.name)}</span></div>`).join(''):'<p class="muted">尚無貓咪</p>'}</div><button class="btn secondary" data-add-cat="${o.id}" style="margin-top:10px">＋ 新增貓咪</button></article>`).join('')}
function ownerDialog(){const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><div class="drawer-head"><h2>新增飼主</h2><button class="icon-btn" aria-label="關閉">✕</button></div><form><div class="form-grid two"><div class="field"><label>姓名 *</label><input name="name" required maxlength="80"></div><div class="field"><label>手機 *</label><input name="phone" required inputmode="tel" maxlength="30"></div><div class="field"><label>LINE 聯絡</label><input name="lineContact" maxlength="100"></div><div class="field"><label>Email</label><input name="email" type="email" maxlength="200"></div><div class="field"><label>緊急聯絡人</label><input name="emergencyContact" maxlength="80"></div><div class="field"><label>緊急電話</label><input name="emergencyPhone" inputmode="tel" maxlength="30"></div></div><div class="field"><label>慣用獸醫院</label><input name="preferredVet" maxlength="200"></div><div class="field"><label>備註</label><textarea name="notes" maxlength="2000"></textarea></div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">儲存飼主</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;setSync('儲存中','saving');try{await state.repo.createOwner(Object.fromEntries(new FormData(form)));setSync('已儲存');dialog.close();profilesPage()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false;setSync('儲存失敗','error')}};closeDialogHandlers(dialog);dialog.showModal()}
function catDialog(ownerId,ownerName){const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><div class="drawer-head"><h2>新增貓咪｜${esc(ownerName)}</h2><button class="icon-btn" aria-label="關閉">✕</button></div><form><div class="form-grid two"><div class="field"><label>名字 *</label><input name="name" required maxlength="80"></div><div class="field"><label>品種</label><input name="breed" maxlength="100"></div><div class="field"><label>性別</label><select name="sex"><option value="unknown">未知</option><option value="female">母</option><option value="male">公</option></select></div><div class="field"><label>出生日期</label><input name="birthDate" type="date"></div><div class="field"><label>體重（kg）</label><input name="weight" type="number" min="0.01" max="99" step="0.01"></div><div class="field"><label>結紮</label><select name="neutered"><option value="">未知</option><option value="true">已結紮</option><option value="false">未結紮</option></select></div></div>${[['allergies','過敏'],['chronicConditions','慢性病'],['foodRestrictions','飲食限制'],['medicationInfo','用藥資訊'],['specialCare','特殊照護'],['emergencyInstructions','緊急指示']].map(([name,label])=>`<div class="field"><label>${label}</label><textarea name="${name}" maxlength="2000"></textarea></div>`).join('')}<p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">儲存貓咪</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(form));payload.ownerId=ownerId;const button=form.querySelector('[type=submit]');button.disabled=true;setSync('儲存中','saving');try{await state.repo.createCat(payload);setSync('已儲存');dialog.close();profilesPage()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false;setSync('儲存失敗','error')}};closeDialogHandlers(dialog);dialog.showModal()}
async function settingsPage(){if(!state.cloud)return sectionInfoFallback('系統設定','連接 Supabase 後可設定實體房間、人員與旅館選項。');main.innerHTML='<section class="loading-card"><span class="spinner"></span><p>載入設定…</p></section>';try{const [types,rooms]=await Promise.all([state.repo.roomTypes(),state.repo.rooms()]);const canEdit=state.membership.role==='owner';main.innerHTML=`<div class="page-head"><div><p>僅業主可修改主檔</p><h2>系統設定</h2></div><button class="btn secondary" id="backMore">返回</button></div><section class="card"><div class="page-head"><div><h3>實體房間</h3><p>原始專案只有房型，請依現場新增房名。</p></div>${canEdit?'<button class="btn" id="addRoom">＋ 房間</button>':''}</div><div class="list">${rooms.length?rooms.map(r=>`<div class="list-item"><div><strong>${esc(r.name)}</strong><p>${esc(r.room_types?.name)}｜${esc(ROOM_STATUS_LABELS[r.status]||r.status)}</p></div></div>`).join(''):'<p class="muted">尚未建立實體房間</p>'}</div></section><section class="card" style="margin-top:14px"><h3>房型與既有價格</h3><div class="list">${types.map(t=>`<div class="list-item"><span>${esc(t.name)}</span><span class="badge">最多 ${t.max_cats} 隻</span></div>`).join('')}</div></section><section class="card" style="margin-top:14px"><h3>人員權限</h3><p class="muted">邀請、停用與角色調整的 Edge Function 已建立；管理畫面尚待後續里程碑。</p></section>`;document.querySelector('#backMore').onclick=()=>route('more');if(canEdit)document.querySelector('#addRoom').onclick=()=>roomDialog(types)}catch(error){renderFatal(error)}}
function roomDialog(types){const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><h2>新增實體房間</h2><form><div class="field"><label>房名／房號 *</label><input name="name" required maxlength="100" placeholder="例如：爵士房 1"></div><div class="field"><label>房型 *</label><select name="roomTypeId" required>${types.map(t=>`<option value="${t.id}">${esc(t.name)}（最多 ${t.max_cats} 隻）</option>`).join('')}</select></div><p class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">建立房間</button><button class="btn secondary" type="button" data-close>取消</button></div></form></div>`;document.body.append(dialog);const form=dialog.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await state.repo.createRoom(Object.fromEntries(new FormData(form)));setSync('已儲存');dialog.close();settingsPage()}catch(error){form.querySelector('[role=alert]').textContent=error.message;button.disabled=false}};closeDialogHandlers(dialog);dialog.showModal()}
function sectionInfoFallback(title,text){const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><h2>${title}</h2><p>${text}</p><button class="btn" id="ok">知道了</button></div>`;document.body.append(dialog);dialog.querySelector('#ok').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal()}
function legacyDialog(){const found=discoverLegacy(),result=validateLegacyBundle(found);const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><h2>舊版資料安全移轉</h2><p>找到 ${found.length} 個已知舊版資料來源；${result.valid?'格式檢查完成':'有資料無法解析'}。</p>${result.issues.map(i=>`<p class="error">${esc(i.key)}：${esc(i.message)}</p>`).join('')}<p class="muted">匯出不會刪除或修改瀏覽器資料。正式匯入前會預覽、去重並由資料庫驗證租戶關聯。</p><div class="actions"><button class="btn secondary" id="download" ${found.length?'':'disabled'}>下載 JSON 備份</button><button class="btn" id="close">關閉</button></div></div>`;document.body.append(dialog);dialog.querySelector('#close').onclick=()=>dialog.close();dialog.querySelector('#download').onclick=()=>{const blob=new Blob([exportLegacyBackup()],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`mumao-legacy-${taipeiDate()}.json`;a.click();URL.revokeObjectURL(a.href)};dialog.onclose=()=>dialog.remove();dialog.showModal()}
boot();
